inline std::string get_icon_svg(const std::string& icon_name, float size = 24, const std::string& color = "#333") {
    const auto& icons = get_icon_paths();
    auto it = icons.find(icon_name);
    if (it == icons.end()) return "";
    
    return "<svg xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 24 24\" width=\"" 
           + std::to_string((int)size) + "\" height=\"" + std::to_string((int)size) + "\">"
           "<path fill=\"" + color + "\" d=\"" + it->second + "\"/></svg>";
}

inline bool has_icon(const std::string& icon_name) {
    return get_icon_paths().count(icon_name) > 0;
}

